// Returns a string name for the kind value returned by GetKind, mapping 0-4 to DEFAULT, ACTION, SCRIPT, COMBAT, DIALOG and default to NONE.
// @fnv 0x009016a0
const char* FUN_009016a0_cls::GetKindName()
{
    switch (GetKind())
    {
    case 0:
        return "DEFAULT";
    case 1:
        return "ACTION";
    case 2:
        return "SCRIPT";
    case 3:
        return "COMBAT";
    case 4:
        return "DIALOG";
    default:
        return "NONE";
    }
}

